sql.data:
delete from attributes;
delete from MES;
insert into attributes
      WITH split(word, str, hascomma) AS (
    select '', attributes, 1 from AllME
    UNION ALL SELECT
    substr(str, 0, 
        case when instr(str, ',')
        then instr(str, ',')
        else length(str)+1 end),
    ltrim(substr(str, instr(str, ',')), ','),
    instr(str, ',')
    FROM split
    WHERE hascomma
)
SELECT distinct substr(trim(word),0,instr(trim(word),'=')) FROM split WHERE word!='';

insert into MES
select * from 
(
    select ME.name as name, A.name as attributes,instr(ME.attributes,A.name) as value from AllME ME, attributes A
);
